import glob,re
for f in sorted(glob.glob('*.txt')):
 t=open(f).read(); page='?'; lines=t.splitlines(); hits=[]
 for i,l in enumerate(lines):
  m=re.search(r'--- page (\\d+) ---',l)
  if m: page=m.group(1)
  if re.search(r'compet|exclusiv|similar (business|platform)|same business',l,re.I):
   hits.append(f'p.{page}: '+ ' '.join(lines[max(0,i-1):min(len(lines),i+3)]))
 print('\\nFILE:',f,'\\n'+'\\n'.join(hits))
