import glob,re
patterns={'AMERICAS':r'6\\.1','ICORE':r'unique.position','LEGACY':r'competitive','LOGANS':r'competitive|competes|compete with','MANAKOA':r'competitor','SLINGER':r'NON-COMPETITION','DYNAMEX':r'42.0','Xpresspa':r'3.01'}
